export function vocabulary(input: Input) {
  return (
    input.alpha +
    input.beta +
    input.gamma +
    input.delta +
    input.epsilon +
    input.zeta +
    input.eta +
    input.theta +
    input.iota +
    input.kappa +
    input.lambda +
    input.mu +
    input.nu +
    input.xi +
    input.omicron +
    input.pi +
    input.rho +
    input.sigma +
    input.tau +
    input.upsilon +
    input.phi +
    input.chi +
    input.psi +
    input.omega +
    input.aleph
  );
}
